// src/models/Product.js
const mongoose = require('mongoose');
const ProductSchema = new mongoose.Schema({
  asin: String,
  url: String,
  name: String,
  trackedBy: [Number],
  thresholdPrice: Number,
  priceHistory: [
    { price: Number, date: Date }
  ]
});
module.exports = mongoose.model('Product', ProductSchema);
